import { LANG_STRINGS } from '../../constants/lang'
import { Input, Form, DatePicker, Radio, Select, InputNumber, Checkbox, notification, Button, Icon } from 'antd'
import { isArray, get } from 'lodash'
import NumericInput from '../NumericInput'
import FloatLabel from '../FormFloatLabel'
import sanitizeInput from './sanitizedInput'
import { REGEX } from '../../constants/regex'
