export function getFormItems (formData) {
  const { getFieldDecorator, getFieldValue } = this.props.form

  const {
    disableField,
    type, label = ' ',
    initialValue,
    required = false,
    reactLabel = '',
    placeHolder = ' ',
    className = ' ',
    extra = ' ',
    btnText,
    btnLoading = false,
    verifiedEmail,
    emailwarning
  } = formData

  switch (type) {
    case 'numeric':
      return (
        <Form.Item extra={this.intlText({ id: extra })} label={reactLabel || this.intlText({ id: label })}>
          {
            getFieldDecorator(formData.formName, {
              rules: [
                {
                  required: required,
                  message: (<IntlMessages id={LANG_STRINGS.requiredField} />)
                },
                { validator: formData.validator }
              ],
              initialValue: initialValue || ''
            })(
              <InputNumber
                disabled={disableField !== undefined ? disableField : !!initialValue}
                placeholder={this.intlText({ id: placeHolder })}
                className={className} />
            )
          }
        </Form.Item>
      )
    case 'alphanumeric':
      return (
        <Form.Item extra={extra !== ' ' ? this.intlText({ id: extra }) : ''} label={reactLabel || this.intlText({ id: label })}>
          {
            getFieldDecorator(formData.formName, {
              rules: [
                {
                  required: required,
                  message: (<IntlMessages id={LANG_STRINGS.requiredField} />)
                },
                { validator: formData.validator }
              ],
              initialValue: initialValue || ''
            })(
              <Input
                disabled={disableField !== undefined ? disableField : !!initialValue}
                placeholder={this.intlText({ id: placeHolder })}
                className={className} />
            )
          }
        </Form.Item>
      )
    case 'alphanumericFloating':
      return (
        <Form.Item >
          <FloatLabel extra={extra !== ' ' ? this.intlText({ id: extra }) : ''} label={reactLabel || this.intlText({ id: label })} value={getFieldValue(formData.formName)}>
            {
              getFieldDecorator(formData.formName, {
                rules: [
                  {
                    required: required,
                    message: (<IntlMessages id={LANG_STRINGS.requiredField} />)
                  },
                  { validator: formData.validator }
                ],
                initialValue: initialValue || ''
              })(
                <Input
                  disabled={disableField !== undefined ? disableField : !!initialValue}
                  className={className}
                  // onChange={e => setFirstName(e.target.value)}
                />
              )
            }
          </FloatLabel>
        </Form.Item>
      )
    case 'alphanumericRestrict':
      return (
        <Form.Item >
          <FloatLabel label={reactLabel || this.intlText({ id: label })} value={getFieldValue(formData.formName)}>
            {
              getFieldDecorator(formData.formName, {
                rules: [
                  {
                    required: required,
                    message: (<IntlMessages id={LANG_STRINGS.requiredField} />)
                  },
                  { validator: formData.validator }
                ],
                initialValue: initialValue || ''
              })(
                <Input
                  disabled={disableField !== undefined ? disableField : !!initialValue}
                  className={className}
                  onChange={(e) => {
                    sanitizeInput(e, REGEX.alphaNumbericValidator)
                  }}
                />
              )
            }
          </FloatLabel>
        </Form.Item>
      )
    case 'textarea':
      return (
        <Form.Item label={this.intlText({ id: label })} className={className}>
          {
            getFieldDecorator(formData.formName, {
              rules: [
                {
                  required: required,
                  message: (<IntlMessages id={LANG_STRINGS.requiredField} />)
                },
                { validator: formData.validator }
              ],
              initialValue: ''
            })(<Input.TextArea
              rows={formData.row || 4}
              className='address-textarea'
              placeholder={this.intlText({ id: placeHolder })}
            />)
          }
        </Form.Item>
      )
    case 'dob':
      return (
        <Form.Item label={this.intlText({ id: label })}>
          {
            getFieldDecorator(formData.formName, {
              rules: [
                {
                  required: required,
                  message: (<IntlMessages id={LANG_STRINGS.requiredField} />)
                },
                { validator: formData.validator }
              ],
              initialValue: ''
            })(
              <DatePicker
                className={className}
                format={'YYYY-MM-DD'}
                placeholder={this.intlText({ id: placeHolder })}
              // disable selection above today
              />
            )
          }
        </Form.Item>
      )
    case 'number':
      return (
        <Form.Item >
          <FloatLabel extra={extra !== ' ' ? this.intlText({ id: extra }) : ''} label={reactLabel || this.intlText({ id: label })} value={getFieldValue(formData.formName)}>
            {
              getFieldDecorator(formData.formName, {
                rules: [
                  {
                    required: required,
                    message: (<IntlMessages id={LANG_STRINGS.requiredField} />)
                  },
                  { validator: formData.validator }
                ],
                initialValue: initialValue || ''
              })(
                <Input
                  className={className}
                  type='number'
                  placeholder={this.intlText({ id: placeHolder })}
                  style={{ width: '100%' }}
                // disable selection above today
                />
              )
            }
          </FloatLabel>
        </Form.Item>
      )
    case 'date':
      return (
        <Form.Item >
          <FloatLabel extra={extra !== ' ' ? this.intlText({ id: extra }) : ''} label={reactLabel || this.intlText({ id: label })} value={getFieldValue(formData.formName)}>
            {
              getFieldDecorator(formData.formName, {
                rules: [
                  {
                    required: required,
                    message: (<IntlMessages id={LANG_STRINGS.requiredField} />)
                  },
                  { validator: formData.validator }
                ],
                initialValue: initialValue || ''
              })(
                <DatePicker
                  className={className}
                  format={'YYYY-MM-DD'}
                  placeholder={this.intlText({ id: placeHolder })}
                  style={{ width: '100%' }}
                // disable selection above today
                />
              )
            }
          </FloatLabel>
        </Form.Item>
      )
    case 'email':
      return (
        <Form.Item label={this.intlText({ id: label })}>
          {
            getFieldDecorator(formData.formName, {
              rules: [
                { required: true, message: this.intlText({ id: LANG_STRINGS.emailRequired }) },
                { type: 'email', message: this.intlText({ id: LANG_STRINGS.emailError }) }
              ],
              initialValue: initialValue
            })(
              <Input disabled={!!initialValue} placeholder={this.intlText({ id: placeHolder })} />
            )
          }
        </Form.Item>
      )
    case 'radio':
      const { option } = formData
      return (
        <Form.Item label={this.intlText({ id: label })}>
          {getFieldDecorator(formData.formName, {
            rules: [
              {
                required: required,
                message: (<IntlMessages id={LANG_STRINGS.requiredField} />)
              },
              { validator: formData.validator }
            ],
            initialValue: ''
          })(
            <Radio.Group>
              {
                option.map((item, index) => {
                  return (
                    <Radio key={index} value={item.value}>
                      {this.intlText({ id: item.displayName })}
                    </Radio>
                  )
                })
              }
            </Radio.Group>
          )}
        </Form.Item>
      )
    case 'choices':
      return (
        <Form.Item label={this.intlText({ id: label })}>
          {getFieldDecorator(formData.formName, {
            rules: [
              {
                required: required,
                message: (<IntlMessages id={LANG_STRINGS.requiredField} />)
              },
              { validator: formData.validator }
            ]
          })(
            <Select
              // disabled={disableField}
              showSearch
              placeholder={this.intlText({ id: placeHolder })}
              style={{ width: '100%' }}
              filterOption={(input, option) =>
                option.props.children
                  .toLowerCase()
                  .indexOf(input.toLowerCase()) >= 0
              }
              className={className}
            >
              {
                formData.options.map((option, index) => {
                  return (
                    <Select.Option key={index} value={option[formData.optionKey]}>
                      {this.intlText({ id: formData.choicesRenderKey ? option[formData.choicesRenderKey] : option[formData.optionKey] })}
                    </Select.Option>
                  )
                })
              }
            </Select>)
          }
        </Form.Item>
      )
    case 'checkbox':
      return (
        <Form.Item className={className}>
          {getFieldDecorator(formData.formName, {
            rules: [
              {
                required: required,
                message: (<IntlMessages id={LANG_STRINGS.requiredField} />)
              },
              { validator: formData.validator }
            ]
          })(<Checkbox><IntlMessages id={label} /></Checkbox>)
          }
        </Form.Item>
      )
    case 'phone_no':
      return (
        <Form.Item label={this.intlText({ id: label })} className={className}>
          {getFieldDecorator(formData.formName, {
            rules: [
              {
                required: required,
                message: (<IntlMessages id={LANG_STRINGS.requiredField} />)
              },
              { validator: formData.validator }
            ]
          })(<NumericInput
            className={className}
            addonBefore='+62'
            minLength={formData.minLength || 10}
            maxLength={formData.maxLength || 30}
          />)
          }
        </Form.Item>
      )
    case 'verifyemail':
      return (
        <div className='verify-container'>
          <Form.Item>
            <FloatLabel extra={extra !== ' ' ? this.intlText({ id: extra }) : ''} label={reactLabel || this.intlText({ id: label })} value={getFieldValue(formData.formName) || initialValue}>
              {
                getFieldDecorator(formData.formName, {
                  initialValue: initialValue
                })(
                  <Input disabled={!!disableField} placeholder={this.intlText({ id: placeHolder })}
                    suffix={verifiedEmail ? <Icon type='check-circle' theme='twoTone' twoToneColor='#52c41a' /> : null}
                    onChange={(e) => {
                      sanitizeInput(e, REGEX.emailValidator)
                    }}
                  />
                )
              }
            </FloatLabel>
          </Form.Item>

          {
            btnText && !initialValue &&
            <Button
              disabled={!getFieldValue(formData.formName)?.length}
              loading={btnLoading}
              onClick={() => this.handleVerifyModalOpen(initialValue)}
            ><IntlMessages id={btnText} /></Button>
          }

          <div className={!initialValue ? 'verify-warning' : 'verify-warning top-0'}>
            <Icon type='info-circle' /> &nbsp;
            <IntlMessages id={emailwarning} />
          </div>
        </div>
      )
    default:
      return null
  }
}

export function errorHandler (error) {
  const {
    submitError,
    detailMessage,
    resetFunction
  } = error
  if (!submitError && (detailMessage && detailMessage !== 'success')) {
    if (isArray(detailMessage)) {
      detailMessage.forEach(item => {
        if (get(item, 'key', '')) {
          this.props.form.setFields({
            [item.key]: {
              value: item.val,
              errors: [new Error(item.err)]
            }
          })
        } else {
          notification['error']({
            message: this.intlText({ id: 'Error' }),
            description: this.intlText({ id: item.err })
          })
        }
      })
      resetFunction()
    } else {
      notification['error']({
        message: this.intlText({ id: 'Error' }),
        description: this.intlText({ id: detailMessage })
      })
      resetFunction()
    }
  }
}
